  const file = await resolveGitExecutable(options)
  if (!file) return null
  const unchanged = { file, env: async (base: NodeJS.ProcessEnv) => ({ ...base }) }
  if ((options.platform ?? process.platform) !== 'win32') return unchanged
  const parent = win32.dirname(file)
