  return (command ??= resolveGitCommand()
    .then((found) => {
      if (!found) command = undefined
      return found
    })
    .catch((error) => {
      command = undefined
      throw error
    }))
}
export async function gitExecutable(): Promise<string | null> {
  return (await gitCommand())?.file ?? null
}

