  return { pool: reasons.length > 0 ? 'io' : 'unit', reasons }
}

/**
 * `appDir/src` 아래 `*.test.ts` 를 풀별로 가른다. 경로는 `src/…` posix, 정렬.
 * `ioSqlite` 는 io 중 `sqlite` 신호가 있는 파일 — `sqlite-serial` 모드가 따로 직렬로 둔다.
